        'num_gamma_archetypes': 8, # HYPOTHESIS: Increased from 4
        'gating_hidden_dim': 32,
        'adam_eps': 1e-8, 'clip_norm': 1.0
    }

def create_network(hparams): 
    # Using the new robust wrapper to prevent parameter mismatch errors
    sota_params = {'rank_k': hparams['rank_k'], 'proj_rank': hparams['proj_rank'], 'hidden_size': hparams['hidden_size'], 'drop': hparams['drop']}
    gating_params = {'num_experts': hparams['num_gamma_archetypes'], 'hidden_dim': hparams['gating_hidden_dim']}

    # The wrapper now needs the class itself, not an instance
    class MoLR_Wrapper(BaseWrapper):
        def __init__(self, hparams):
            # Define a new model class on the fly for the wrapper to inspect
            class MoLR_Model(MoLR_2DGater):
                def __init__(self, rank_k, proj_rank, hidden_size, drop, num_gamma_archetypes, gating_hidden_dim):
